"""Generator for out/w2-A.workflow.json (brief A). Run: python3 /tmp/w2a/gen.py <out path>"""
import json, sys

BASE = "https://freya-bank-mock.freyavoice.workers.dev/v1/"
DEAD = "http://127.0.0.1:9/blocked_by_rules"

# ---------------------------------------------------------------- code node (dates, account facts)
FACTS_CODE = r'''
import json, re, datetime
HOL = set(['2026-10-26', '2026-11-11', '2026-11-26', '2026-12-25', '2027-01-01'])
WD = ['Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday', 'Sunday']
MN = ['January', 'February', 'March', 'April', 'May', 'June', 'July', 'August', 'September', 'October', 'November', 'December']
def isbd(d):
    return d.weekday() < 5 and d.isoformat() not in HOL
def say(d):
    return WD[d.weekday()] + ' ' + str(d.day) + ' ' + MN[d.month - 1] + ' ' + str(d.year)
def lab(d):
    return say(d) + ' (' + d.isoformat() + ')'
def nth_bd_after(d, n):
    x = d
    c = 0
    while c < n:
        x = x + datetime.timedelta(days=1)
        if isbd(x):
            c += 1
    return x
def next_bd(d):
    return nth_bd_after(d, 1)
def money(v):
    try:
        return '%.2f' % float(v)
    except Exception:
        return str(v)
def num(v):
    try:
        return float(v)
    except Exception:
        return None
try:
    raw = str(vars.get('now') or '')
    m = re.match(r'(\d{4})-(\d{1,2})-(\d{1,2})(?:[T ](\d{1,2}):(\d{2}))?', raw)
    if m:
        today = datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
        hh = int(m.group(4) or 9)
        mm = int(m.group(5) or 0)
    else:
        today = datetime.date.today()
        hh, mm = 9, 0
    now_hm = '%02d:%02d' % (hh, mm)
    vars['today_iso'] = today.isoformat()
    vars['today_words'] = say(today)
    vars['now_hm'] = now_hm
    # ---- callback window
    nbd = next_bd(today)
    nowmin = hh * 60 + mm
    cb_today_ok = nowmin < 19 * 60
    vars['cb_today_iso'] = today.isoformat()
    vars['cb_next_iso'] = nbd.isoformat()
    vars['cb_now_min'] = str(nowmin)
    if cb_today_ok:
        t_today = 'today, ' + lab(today) + ', at a time later than ' + now_hm + ' and between 10:00 and 19:00'
    else:
        t_today = 'not today (it is already after 19:00)'
    vars['callback_facts'] = ('A callback can be booked only ' + t_today + '; or on ' + lab(nbd) +
                              ' between 10:00 and 19:00, both included. Any other day or time is outside the window.')
    # ---- week words
    mon = today - datetime.timedelta(days=today.weekday())
    words = ['Today is ' + lab(today) + '. Tomorrow is ' + lab(today + datetime.timedelta(days=1)) + '.']
    words.append('This week: ' + '; '.join('this ' + WD[i] + ' = ' + lab(mon + datetime.timedelta(days=i)) for i in range(7)) + '.')
    words.append('Next week: ' + '; '.join('next ' + WD[i] + ' = ' + lab(mon + datetime.timedelta(days=7 + i)) for i in range(7)) + '.')
    vars['week_words'] = '\n'.join(words)
    # ---- account
    prods = None
    for key in ('products', 'load_account_response.data.products', 'get_account_response.data.products'):
        v = vars.get(key)
        if isinstance(v, str):
            try:
                v = json.loads(v)
            except Exception:
                try:
                    import ast
                    v = ast.literal_eval(v)
                except Exception:
                    v = None
        if isinstance(v, list) and v:
            prods = v
            break
    if prods is None:
        flat = dict()
        for k in list(vars.keys()):
            mm2 = re.search(r'products\.(\d+)\.(\w+)$', str(k))
            if mm2:
                flat.setdefault(int(mm2.group(1)), dict())[mm2.group(2)] = vars.get(k)
        if flat:
            prods = [flat[i] for i in sorted(flat)]
    p = None
    if prods:
        cands = [x for x in prods if isinstance(x, dict)]
        late = [x for x in cands if (num(x.get('past_due')) or 0) > 0]
        p = (late or cands or [None])[0]
    if p:
        ptype = str(p.get('type') or '')
        if ptype == 'credit_card':
            pw = 'credit card ending ' + str(p.get('card_last4') or '')
            floor = num(p.get('minimum_payment'))
            floor_name = 'minimum payment'
        elif ptype == 'car_loan':
            pw = 'car loan'
            floor = num(p.get('instalment_amount'))
            floor_name = 'instalment amount'
        else:
            pw = 'personal loan'
            floor = num(p.get('instalment_amount'))
            floor_name = 'instalment amount'
        full = num(p.get('past_due')) or 0.0
        if floor is None or floor > full:
            floor = full
        try:
            dl = int(float(p.get('days_late')))
        except Exception:
            dl = 1
        band = 'early' if dl <= 7 else 'late'
        attempts = 1 if band == 'early' else 2
        deadline = nth_bd_after(today, 12 if band == 'early' else 7)
        # attempt 1 date: last business day of this week, or of next week if today is that day
        def last_bd_of_week(monday):
            for i in range(6, -1, -1):
                d = monday + datetime.timedelta(days=i)
                if isbd(d):
                    return d
            return None
        a1 = last_bd_of_week(mon)
        if a1 is None or a1 <= today:
            a1 = last_bd_of_week(mon + datetime.timedelta(days=7))
        if a1 is None or a1 > deadline:
            a1 = deadline
        allowed = []
        d = today
        while d <= deadline:
            if isbd(d):
                allowed.append(d)
            d = d + datetime.timedelta(days=1)
        cal = []
        d = today
        end = deadline + datetime.timedelta(days=10)
        while d <= end:
            if d > deadline:
                note = 'AFTER the deadline, cannot be recorded; the latest date is ' + say(deadline)
            elif isbd(d):
                note = 'valid promise date'
            else:
                why = 'bank holiday' if d.isoformat() in HOL else 'weekend'
                note = why + ', not a business day; offer the next business day instead: ' + say(next_bd(d))
            cal.append('- ' + lab(d) + ': ' + note)
            d = d + datetime.timedelta(days=1)
        vars['product_id'] = str(p.get('product_id') or '')
        vars['product_words'] = pw
        vars['full_amt'] = money(full)
        vars['floor_amt'] = money(floor)
        vars['floor_name'] = floor_name
        vars['days_late'] = str(dl)
        vars['band'] = band
        vars['attempts_allowed'] = str(attempts)
        vars['deadline_iso'] = deadline.isoformat()
        vars['deadline_words'] = lab(deadline)
        vars['attempt1_words'] = lab(a1)
        vars['allowed_dates'] = ','.join(x.isoformat() for x in allowed)
        vars['account_state'] = 'ok'
        vars['debt_line'] = ('Thank you, ' + str(vars.get('title') or '') + ' ' + str(vars.get('last_name') or '') +
                             '. I am calling from the collections team about a late payment on your ' + pw +
                             '. The past-due amount is ' + money(full) + ' and the payment is ' + str(dl) +
                             ' days late. Can you make this payment today?')
        if attempts == 2:
            att = ('Attempt 1: propose the amount (full past-due amount ' + money(full) + ', or the floor ' + money(floor) +
                   ' if the customer already said the full amount is too much) on ' + lab(a1) + '.\n'
                   'Attempt 2: propose the floor amount ' + money(floor) + ' on the deadline ' + lab(deadline) + '.')
        else:
            att = ('Attempt 1 (the only one): propose the amount (full past-due amount ' + money(full) + ', or the floor ' +
                   money(floor) + ' if the customer already said the full amount is too much) on ' + lab(a1) + '.\n'
                   'There is no attempt 2 in this band.')
        vars['account_facts'] = '\n'.join([
            'Product: ' + pw + ' (product_id ' + str(p.get('product_id') or '') + ').',
            'Full past-due amount: ' + money(full) + '. Days late: ' + str(dl) + '.',
            'Floor amount (' + floor_name + '): ' + money(floor) + '.',
            'Band: ' + band + '. Persuasion attempts allowed: ' + str(attempts) + '.',
            'Deadline (latest date a promise can be recorded): ' + lab(deadline) + '.',
            'Valid promise dates: ' + ', '.join(lab(x) for x in allowed) + '.',
            att,
            'Calendar:',
        ] + cal)
    else:
        vars['account_state'] = 'error'
        vars['product_id'] = ''
        vars['allowed_dates'] = ''
        vars['full_amt'] = '0'
        vars['floor_amt'] = '0'
        vars['debt_line'] = 'Thank you. I am sorry, I cannot access your account details right now.'
        vars['account_facts'] = 'The account could not be loaded. You have no account information.'
except Exception as e:
    vars.setdefault('today_words', str(vars.get('now') or ''))
    vars.setdefault('callback_facts', 'A callback can be booked today later than now, or on the next business day, between 10:00 and 19:00.')
    vars.setdefault('week_words', '')
    vars.setdefault('account_state', 'error')
    vars.setdefault('debt_line', 'Thank you. I am sorry, I cannot access your account details right now.')
    vars.setdefault('account_facts', 'The account could not be loaded. You have no account information.')
    vars.setdefault('allowed_dates', '')
    vars['facts_error'] = str(e)[:200]
'''

