        m = re.match(r'^(\d{1,2})[:.h]?(\d{2})?', tm)
        ok = False
        why = ''
        if m:
            h = int(m.group(1))
            mi = int(m.group(2) or 0)
            tm = '%02d:%02d' % (h, mi)
            b['time'] = tm
            tmin = h * 60 + mi
            inwin = 600 <= tmin <= 1140
            try:
                nowmin = int(vars.get('cb_now_min') or 0)
            except Exception:
                nowmin = 0
            if dt == str(vars.get('cb_today_iso')):
                ok = inwin and tmin > nowmin
            elif dt == str(vars.get('cb_next_iso')):
                ok = inwin
            if not ok:
                why = 'The day or the time ' + dt + ' ' + tm + ' is outside the callback window.'
        else:
            why = 'The time is missing or unreadable.'
        if ok:
            vars['cb_blocked'] = ''
        else:
            vars['cb_blocked'] = why or 'outside the window'
            config['url'] = '__DEAD__'
except Exception:
    pass
'''.replace('__DEAD__', DEAD)

