def conv(name, task, tools, transitions, on_enter, extraction=None):
    n = {
        "name": name, "node_type": "conversation", "task_message": task, "tools": tools,
        "on_enter": on_enter, "on_enter_first_entry_only": True, "transitions": transitions,
        "max_node_turns": 60, "truncation_strategy": "keep_all", "suppress_tool_results": False,
    }
    if extraction:
        n["extraction_schema"] = extraction
    return n


def code_node(name, nxt):
